    18→func (s *Service) maintainCustodyInfo() {
    19→	const interval = 1 * time.Minute
    20→
    21→	async.RunEvery(s.ctx, interval, func() {
    22→		if err := s.updateCustodyInfoIfNeeded(); err != nil {
    23→			log.WithError(err).Error("Failed to update custody info")
    24→		}
    25→	})
    26→}
    27→
    28→func (s *Service) updateCustodyInfoIfNeeded() error {
    29→	const minimumPeerCount = 1
    30→
    31→	// Get our actual custody group count.
    32→	actualCustodyGrounpCount, err := s.cfg.p2p.CustodyGroupCount()
    33→	if err != nil {
    34→		return errors.Wrap(err, "p2p custody group count")
    35→	}
    36→
    37→	// Get our target custody group count.
    38→	targetCustodyGroupCount, err := s.custodyGroupCount()
    39→	if err != nil {
    40→		return errors.Wrap(err, "custody group count")
    41→	}
    42→
    43→	// If the actual custody group count is already equal to the target, skip the update.
    44→	if actualCustodyGrounpCount >= targetCustodyGroupCount {
    45→		return nil
    46→	}
    47→
    48→	// Check that all subscribed data column sidecars topics have at least `minimumPeerCount` peers.
    49→	topics := s.cfg.p2p.PubSub().GetTopics()
    50→	enoughPeers := true
    51→	for _, topic := range topics {
    52→		if !strings.Contains(topic, p2p.GossipDataColumnSidecarMessage) {
    53→			continue
    54→		}
    55→
    56→		if peers := s.cfg.p2p.PubSub().ListPeers(topic); len(peers) < minimumPeerCount {
    57→			// If a topic has fewer than the minimum required peers, log a warning.
    58→			log.WithFields(logrus.Fields{
    59→				"topic":            topic,
    60→				"peerCount":        len(peers),
    61→				"minimumPeerCount": minimumPeerCount,
    62→			}).Debug("Insufficient peers for data column sidecar topic to maintain custody count")
    63→			enoughPeers = false
    64→		}
    65→	}
    66→
    67→	if !enoughPeers {
    68→		return nil
    69→	}
    70→
    71→	headROBlock, err := s.cfg.chain.HeadBlock(s.ctx)
    72→	if err != nil {
    73→		return errors.Wrap(err, "head block")
    74→	}
    75→	headSlot := headROBlock.Block().Slot()
    76→
    77→	storedEarliestSlot, storedGroupCount, err := s.cfg.p2p.UpdateCustodyInfo(headSlot, targetCustodyGroupCount)
    78→	if err != nil {
    79→		return errors.Wrap(err, "p2p update custody info")
    80→	}
    81→
    82→	if _, _, err := s.cfg.beaconDB.UpdateCustodyInfo(s.ctx, storedEarliestSlot, storedGroupCount); err != nil {
    83→		return errors.Wrap(err, "beacon db update custody info")
    84→	}
    85→
    86→	return nil
    87→}
