    89→// custodyGroupCount computes the custody group count based on the custody requirement,
    90→// the validators custody requirement, and whether the node is subscribed to all data subnets.
    91→func (s *Service) custodyGroupCount() (uint64, error) {
    92→	beaconConfig := params.BeaconConfig()
    93→
    94→	if flags.Get().SubscribeAllDataSubnets {
    95→		return beaconConfig.NumberOfCustodyGroups, nil
    96→	}
    97→
    98→	validatorsCustodyRequirement, err := s.validatorsCustodyRequirement()
    99→	if err != nil {
   100→		return 0, errors.Wrap(err, "validators custody requirement")
   101→	}
   102→
   103→	return max(beaconConfig.CustodyRequirement, validatorsCustodyRequirement), nil
   104→}
   105→
   106→// validatorsCustodyRequirements computes the custody requirements based on the
   107→// finalized state and the tracked validators.
   108→func (s *Service) validatorsCustodyRequirement() (uint64, error) {
   109→	if s.trackedValidatorsCache == nil {
   110→		return 0, nil
   111→	}
   112→	// Get the indices of the tracked validators.
   113→	indices := s.trackedValidatorsCache.Indices()
   114→
   115→	// Return early if no validators are tracked.
   116→	if len(indices) == 0 {
   117→		return 0, nil
   118→	}
   119→
   120→	// Retrieve the finalized state.
   121→	finalizedState := s.cfg.stateGen.FinalizedState()
   122→	if finalizedState == nil || finalizedState.IsNil() {
   123→		return 0, nilFinalizedStateError
   124→	}
   125→
   126→	// Compute the validators custody requirements.
   127→	result, err := peerdas.ValidatorsCustodyRequirement(finalizedState, indices)
   128→	if err != nil {
   129→		return 0, errors.Wrap(err, "validators custody requirements")
   130→	}
   131→
   132→	return result, nil
   133→}
